try{if(Test-Path "$out\$name.json"){throw 'Preserve editor smoke receipt'};if(Test-Path $owned){throw 'Preserve authored editor project copy'};$built=Get-Content "$out\m78-native-final-editor-build-canonical-recovery.json" -Raw|ConvertFrom-Json;if((Get-FileHash $built.executable).Hash.ToLower() -ne $built.executableSHA256 -or (Get-FileHash "$root\M78ContinuationBuild\combined-v2\judas_engine.lib").Hash.ToLower() -ne $built.librarySHA256){throw 'Verified fresh native editor/library mismatch'};Copy-Item "$root\Source\projects\balance_lab" $owned -Recurse;$scene="$owned\Scenes\standing.judas";$before=(Get-FileHash $scene).Hash.ToLower();$env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source";$env:JUDAS_EDITOR_AUTOTEST="$out\editor-autotest";Remove-Item Env:\JUDAS_TEST_SCRIPT -ErrorAction SilentlyContinue;$watch=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process -FilePath $built.executable -WorkingDirectory "$root\Source" -ArgumentList @("$owned\balance_lab.judasproj") -PassThru -RedirectStandardOutput "$out\$name.stdout.log" -RedirectStandardError "$out\$name.stderr.log";[void]$p.Handle;if(!$p.WaitForExit(600000)){Stop-Process -Id $p.Id -Force;$exit='owned native editor timed out'}else{$p.Refresh();$exit=$p.ExitCode};$watch.Stop();$after=(Get-FileHash $scene).Hash.ToLower();$files=@();foreach($f in Get-ChildItem $out -File -Filter 'editor-autotest*'){$n="m78-native-final-$($f.Name)";Upload $f.FullName $n;$files+=@{path=$f.FullName;name=$n;bytes=$f.Length;sha256=(Get-FileHash $f.FullName).Hash.ToLower()}};@{scope='Fresh unchanged-source editor target linked against final physics archive. Ordinary copied project autotest: edit/duplicate/undo/Play/Stop/save; authored scene identity measured before/after. Native software GL functional-only.';exitCode=$exit;seconds=$watch.Elapsed.TotalSeconds;executableSHA256=$built.executableSHA256;librarySHA256=$built.librarySHA256;authoredScene=$scene;sceneBeforeSHA256=$before;sceneAfterSHA256=$after;sceneUnchanged=($before -eq $after);environment=@{GALLIUM_DRIVER=$env:GALLIUM_DRIVER;JUDAS_ENGINE_ROOT=$env:JUDAS_ENGINE_ROOT;JUDAS_EDITOR_AUTOTEST=$env:JUDAS_EDITOR_AUTOTEST};files=$files;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 6|Set-Content "$out\$name.json" -Encoding UTF8;Upload "$out\$name.stdout.log" "$name.stdout.log";Upload "$out\$name.stderr.log" "$name.stderr.log";Upload "$out\$name.json" "$name.json"}catch{[string]$_.Exception.Message|Set-Content "$out\$name-error.txt";Upload "$out\$name-error.txt" "$name-error.txt";exit 1}
